test('addLine rejects invalid discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: 101 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: -1 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'ICON-SET', qty: 2, discountPercent: 'bad' }), { ok: false, error: 'DISCOUNT_INVALID' });
