  assert.equal(r.value.lines[0].discountPercent, 20);
});

test('invoiceTotals works with invoice from createInvoice with discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2, discountPercent: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 3 * 8500 + 2 * 980;
  const expectedDiscount = Math.round((3 * 8500 * 10) / 100) + Math.round((2 * 980 * 5) / 100);
  const line1Total = 3 * 8500 - Math.round((3 * 8500 * 10) / 100);
  const line2Total = 2 * 980 - Math.round((2 * 980 * 5) / 100);
  const expectedVAT = Math.round((line1Total * 21) / 100) + Math.round((line2Total * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVAT);
});

